import math
import sys

class Point:
    def __init__(self, a, b, c, d, e):
        self.v = a
        self.w = b
        self.x = c
        self.y = d
        self.z = e

    def mag(self):
        return math.sqrt(self.v * self.v + self.w * self.w + self.x * self.x + self.y * self.y + self.z * self.z)

def angle(a, b):
    amag = a.mag()
    bmag = b.mag()
    abmag = a.v * b.v + a.w * b.w + a.x * b.x + a.y * b.y + a.z * b.z
    # To prevent floating point errors outside domain of acos
    ratio = abmag / (amag * bmag) if amag != 0 and bmag != 0 else 1
    ratio = min(1, max(-1, ratio))
    angleDeg = math.degrees(math.acos(ratio))
    return angleDeg < 90

def solve():
    input = sys.stdin.read().strip().split('\n')
    n = int(input[0])
    if n > 11:
        print(0)
        return
    points = []
